Definition ipf_W (lo : Z) (sp : word) (P IN E : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp); (P, P + 80); (IN, IN + 8); (E, E + 24); (AG_HTTP_CAT, AG_HTTP_CAT + 64); (AG_FIELD_TABLE, AG_FIELD_TABLE + 3456)]%Z.
Definition ipf_WX (lo : Z) (sp : word) (P IN E ff fp : Z) : list (Z * Z) :=
  ipf_W lo sp P IN E ++ [(as_FSB H, as_FSB H + AFS_FLAGS); (fp, fp + 1); (ff, ff + 8192); (sh ff, sh ff + 1024)]%Z.

(* [comment removed for export] *)
Definition ipf_lay (sp : word) (spa : Z) (gsz : nat) : Prop :=
  spa + 184 + Z.of_nat gsz = bv_unsigned sp + -104 /\ bv_unsigned sp + -304 <= spa /\ spa mod 32 = 0.

(* [comment removed for export] *)
Definition ipf_s1f (P E IN ff : Z) (j96 : list byte) : list cell :=
  [C8 (wz (Z.land (P + 72) 7 + 3)); C8 (wz (sh7 ff + 4)); C8 (wz ff); C8 (wz ff);
   C8 (wz (sh7 P)); C8 (wz (sh7 IN)); C8 (wz (sh7 (P + 72))); C8 (wz (P + 72)); C8 (wz AG_FIELD_TABLE); C8 (wz AG_FIELD_TABLE_GUARD);
   C8 (wz (ff + 32)); C8 (wz (sh7 E)); CB 16 j96; C8 (wz ff)].

