(* [comment removed for export] *)
Definition ipf_retire_stmt : Prop :=
  forall (ra sp gp tp : word) (s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v : word) (F : bvmap 5 word) (fc : bv 32)
    (rax t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s2x s3x s4x s5x s6x s7x s8x s9x s10x s11x t3 t4 t5 t6 : word)
    (LF : list fframe) (m mx : mem) (spa : Z) (gsz : nat) (gj j0 jr jh shb : list byte) (s1r cst chi : list cell) (XS : list (Z * Z))
    (P IN E p0 lo shi ff fp last : Z) (bs : list byte) (c c' : pcore) (pad7 pad2 : list byte) (q qlo : Z) (E' : ecv) (g' : bool)
    (h0 h1 h2 h3 : word),
  rw_cells bsegs mx (spa + 184) [CB gsz gj] ->
  rw_cells bsegs mx (bv_unsigned sp + -104) (dof_sav s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) ->
  rw_cells bsegs mx spa (CB 8 j0 :: C8 (wz (sh7 ff + 4)) :: C8 (wz ff) :: C8 (wz ff) :: s1r) -> Z.of_nat (cells_size s1r) = 88 ->
  rw_cells bsegs mx (spa + 120) cst -> Z.of_nat (cells_size cst) = 24 ->
  rw_cells bsegs mx (spa + 144) chi -> Z.of_nat (cells_size chi) = 40 ->
  rw_cells bsegs mx ff [C8 h0; C8 h1; C8 h2; C8 h3] -> rw_cells bsegs mx (ff + 4136) [CB 4048 jr] -> rw_cells bsegs mx (ff + 8184) [C8 (wz fp)] ->
  rw_cells bsegs mx (Z.shiftr ff 3 + 2147450880) [CB 552 shb] -> rw_cells bsegs mx (Z.shiftr ff 3 + 2147450880 + 552) [CB 472 jh] ->
  rw_cells bsegs mx fp [C1 (b8 1)] ->
  (exists cb, rw_cells bsegs mx (ff + 32) cb /\ Z.of_nat (cells_size cb) = 4104) ->
  stk bsegs mx lo spa -> mem_inv bsegs mx ->
  ipf_side H LF m mx lo shi ff fp P E p0 (Z.of_nat (length bs)) ->
  munch (ipf_WX H lo sp P IN E ff fp ++ XS) m mx -> Forall (fs_scratch H ((7, ff, fp) :: LF)) XS -> wmono bsegs m mx ->
  rw_cells bsegs mx P (ParserCoreCells c' pad7 pad2) -> dof_core c c' ->
  rw_cells bsegs mx IN [C8 (wz q)] -> p0 <= q <= p0 + Z.of_nat (length bs) -> qlo <= q ->
  rw_cells bsegs mx E (ErrCodeCells E') -> (E' = EC_clear \/ http_fail E') -> (E' = EC_clear -> p0 + 2 <= q) ->
  bytes_at bsegs mx p0 bs -> APfTab mx -> (AFieldTabZero mx \/ FT mx) -> FTInit mx -> AHttpCat mx g' ->
  ipf_bpure sp spa gsz P IN E lo shi c p0 last bs -> bv_unsigned ra mod 2 = 0 ->
  evt bsegs (ipf_ret_post H ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc LF P IN E lo shi c pad7 pad2 p0 bs qlo m)
    (MS (mkR rax (wz spa) gp tp t0 t1 t2 sp (wz spa) a0 a1 a2 a3 a4 a5 a6 a7
             s2x s3x s4x s5x s6x s7x s8x s9x s10x s11x t3 t4 t5 t6)
        F (Z_to_bv 64 AIPF_RETIRE) fc None mx (seg_rom bsegs)).
